1	// Package cli implements the user-facing ao command. It stays thin: commands
2	// discover the local daemon, call its loopback HTTP API, and format output.
3	package cli
4	
5	import (
6		"context"
7		"errors"
8		"io"
9		"net/http"
10		"os"
11		"os/exec"
12		"time"
13	
14		"github.com/spf13/cobra"
15	
16		"github.com/aoagents/agent-orchestrator/backend/internal/daemon"
17		"github.com/aoagents/agent-orchestrator/backend/internal/processalive"
18	)
19	
20	// Execute runs the ao CLI with process stdio.
21	func Execute() error {
22		return NewRootCommand(DefaultDeps()).Execute()
23	}
24	
25	// usageError marks a command-line misuse (bad flag, wrong arg count). It lets
26	// the process entrypoint return exit code 2 for usage errors versus 1 for
27	// runtime failures, matching the convention CLIs are scripted against.
28	type usageError struct{ err error }
29	
30	func (e usageError) Error() string { return e.err.Error() }
31	func (e usageError) Unwrap() error { return e.err }
32	
33	// ExitCode maps a CLI error to a process exit code: 2 for usage errors, 1 for
34	// any other failure, 0 for success.
35	func ExitCode(err error) int {
36		if err == nil {
37			return 0
38		}
39		var ue usageError
40		if errors.As(err, &ue) {
41			return 2
42		}
43		return 1
44	}
45	
46	// Deps holds the small set of side effects the CLI needs. Tests replace these
47	// functions without reaching into process-global state.
48	type Deps struct {
49		In  io.Reader
50		Out io.Writer
51		Err io.Writer
52	
53		HTTPClient         *http.Client
54		Executable         func() (string, error)
55		StartProcess       func(processStartConfig) error
56		ProcessAlive       func(pid int) bool
57		LookPath           func(file string) (string, error)
58		CommandOutput      func(ctx context.Context, name string, args ...string) ([]byte, error)
59		CommandOutputInDir func(ctx context.Context, dir, name string, args ...string) ([]byte, error)
60		// DoctorGitHubRESTBase lets tests point the doctor GitHub token probe at
61		// httptest without mutating package-global state.
62		DoctorGitHubRESTBase string
63		Now                  func() time.Time
64		Sleep                func(time.Duration)
65	}
66	
67	// DefaultDeps returns production dependencies.
68	func DefaultDeps() Deps {
69		return Deps{
70			In:                   os.Stdin,
71			Out:                  os.Stdout,
72			Err:                  os.Stderr,
73			HTTPClient:           &http.Client{Timeout: 2 * time.Second},
74			Executable:           os.Executable,
75			StartProcess:         startProcess,
76			ProcessAlive:         processalive.Alive,
77			LookPath:             exec.LookPath,
78			CommandOutput:        commandOutput,
79			CommandOutputInDir:   commandOutputInDir,
80			DoctorGitHubRESTBase: defaultDoctorGitHubRESTBase,
81			Now:                  time.Now,
82			Sleep:                time.Sleep,
83		}
84	}
85	
86	func commandOutput(ctx context.Context, name string, args ...string) ([]byte, error) {
87		return exec.CommandContext(ctx, name, args...).CombinedOutput()
88	}
89	
90	func commandOutputInDir(ctx context.Context, dir, name string, args ...string) ([]byte, error) {
91		cmd := exec.CommandContext(ctx, name, args...)
92		cmd.Dir = dir
93		return cmd.CombinedOutput()
94	}
95	
96	func (d Deps) withDefaults() Deps {
97		def := DefaultDeps()
98		if d.In == nil {
99			d.In = def.In
100		}
101		if d.Out == nil {
102			d.Out = def.Out
103		}
104		if d.Err == nil {
105			d.Err = def.Err
106		}
107		if d.HTTPClient == nil {
108			d.HTTPClient = def.HTTPClient
109		}
110		if d.Executable == nil {
111			d.Executable = def.Executable
112		}
113		if d.StartProcess == nil {
114			d.StartProcess = def.StartProcess
115		}
116		if d.ProcessAlive == nil {
117			d.ProcessAlive = def.ProcessAlive
118		}
119		if d.LookPath == nil {
120			d.LookPath = def.LookPath
121		}
122		if d.CommandOutput == nil {
123			d.CommandOutput = def.CommandOutput
124		}
125		if d.CommandOutputInDir == nil {
126			d.CommandOutputInDir = def.CommandOutputInDir
127		}
128		if d.DoctorGitHubRESTBase == "" {
129			d.DoctorGitHubRESTBase = def.DoctorGitHubRESTBase
130		}
131		if d.Now == nil {
132			d.Now = def.Now
133		}
134		if d.Sleep == nil {
135			d.Sleep = def.Sleep
136		}
137		return d
138	}
139	
140	// NewRootCommand builds a testable root command.
141	func NewRootCommand(deps Deps) *cobra.Command {
142		deps = deps.withDefaults()
143		ctx := &commandContext{deps: deps}
144	
145		root := &cobra.Command{
146			Use:           "ao",
147			Short:         "Agent Orchestrator",
148			Long:          "Agent Orchestrator manages the local daemon that supervises parallel coding-agent sessions.",
149			Version:       VersionString(),
150			SilenceUsage:  true,
151			SilenceErrors: true,
152		}
153		root.SetIn(deps.In)
154		root.SetOut(deps.Out)
155		root.SetErr(deps.Err)
156		root.CompletionOptions.DisableDefaultCmd = true
157		// Tag flag-parse failures as usage errors so the entrypoint can exit 2 for
158		// misuse versus 1 for runtime failures. Subcommands inherit this func.
159		root.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
160			return usageError{err}
161		})
162	
163		root.AddCommand(newDaemonCommand())
164		root.AddCommand(newStartCommand(ctx))
165		root.AddCommand(newStopCommand(ctx))
166		root.AddCommand(newStatusCommand(ctx))
167		root.AddCommand(newDoctorCommand(ctx))
168		root.AddCommand(newSpawnCommand(ctx))
169		root.AddCommand(newSendCommand(ctx))
170		root.AddCommand(newHooksCommand(ctx))
171		root.AddCommand(newProjectCommand(ctx))
172		root.AddCommand(newSessionCommand(ctx))
173		root.AddCommand(newOrchestratorCommand(ctx))
174		root.AddCommand(newCompletionCommand())
175		root.AddCommand(newVersionCommand())
176	
177		return root
178	}
179	
180	type commandContext struct {
181		deps Deps
182	}
183	
184	func noArgs(cmd *cobra.Command, args []string) error {
185		if err := cobra.ExactArgs(0)(cmd, args); err != nil {
186			return usageError{err}
187		}
188		return nil
189	}
190	
191	func newDaemonCommand() *cobra.Command {
192		return &cobra.Command{
193			Use:    "daemon",
194			Short:  "Run the AO backend daemon",
195			Hidden: true,
196			Args:   noArgs,
197			RunE: func(cmd *cobra.Command, args []string) error {
198				return daemon.Run()
199			},
200		}
201	}

